const r=$('ValidateShopifyAndConsent').first().json;
const responses=$input.all().flatMap(item=>{
 let body=item.json.body;
 if(typeof body==='string'){try{body=JSON.parse(body);}catch{throw new Error('trello_batch_invalid_json');}}
 if(!Array.isArray(body)) throw new Error('trello_batch_missing');
 return body;
});
const skip=reason=>[{json:{...r,route:'skip',reason}}];
const evidence={...r.evidence};
if(r.is_test){
 if(responses.length!==1||responses[0]['200']?.id!=='62bae9b97705e7419ed64593') throw new Error('internal_trello_read_failed');
}else{
 if(responses.length!==r.request_ids.length*2) throw new Error('trello_batch_incomplete');
 const cards=[];
 for(let i=0;i<r.request_ids.length;i++){
   const pair=[responses[2*i]['200'],responses[2*i+1]['200']];
   if(pair.some(response=>!response||!Array.isArray(response.cards))) throw new Error('trello_search_failed');
   if(pair.some(response=>response.cards.length>=100)) return skip('trello_search_truncated');
   const id=r.request_ids[i];
   const rx=new RegExp('(^|[^a-z0-9-])'+id+'(?![a-z0-9-])','i');
   const unique=[...new Map(pair.flatMap(response=>response.cards).map(c=>[c.id,c])).values()];
   const matches=unique.filter(c=>c.idBoard==='62bae9b97705e7419ed64593'&&rx.test(String(c.name||'')+' '+String(c.desc||'')));
   if(matches.some(c=>['6347e0a2f062500084675062','646b8c9613dc4e7000f6657e'].includes(c.idList))) return skip('trello_problem_or_resolved');
   if(matches.length===0 || (/^\d{10}$/.test(id)&&matches.length!==1)) return skip('trello_match_missing_or_ambiguous');
   // A request UUID/ticket may have archived design revisions: inspect every exact match.
   cards.push(...matches.map(c=>c.id));
 }
 evidence.trello_result='all_orders_matched_no_problem'; evidence.trello_card_ids=cards;
}
const htmlEscape=s=>String(s).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const template="<div style=\"font-family:Arial,Helvetica,sans-serif;color:#111111;font-size:15px;line-height:1.6;max-width:600px;\">\n        <p style=\"margin:0 0 16px;\">Hallo,</p>\n        <p style=\"margin:0 0 16px;\">ich bin Mika von NEONTRIP und kümmere mich bei uns um den Vertrieb. Sie haben in der Vergangenheit schon einmal bei uns bestellt – deshalb wollte ich kurz nachfragen, ob aktuell wieder ein Projekt ansteht.</p>\n        <p style=\"margin:0 0 16px;\">Planen Sie ein neues Firmenlogo am Empfang, einen Markenauftritt auf einer Messe oder ein Leuchtschild für Ihren Standort? Auch für Projekte Ihrer Kunden setzen wir vorhandene Logos und Designs als Leuchtschilder um.</p>\n        <p style=\"margin:0 0 16px;\">Wenn gerade ein Projekt ansteht, antworten Sie mir einfach mit Ihrem Logo oder Design, der ungefähren gewünschten Breite und dem Einsatzort (innen oder außen). Falls die Details noch offen sind, reichen für den Anfang ein paar Stichworte zu Ihrer Idee.</p>\n        <p style=\"margin:0;\">Viele Grüße</p>\n      </div>\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"font-family:Arial,Helvetica,sans-serif;color:#111111;margin-top:24px;max-width:600px;\">\n        <tbody>\n          <tr><td style=\"padding:16px 0;\">\n            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tbody><tr>\n              <td valign=\"top\" style=\"width:112px;padding-right:16px;\">\n                <img src=\"https://cdn.shopify.com/s/files/1/0534/7819/5350/files/Mika_3.jpg?v=1770127459\" alt=\"Mika Zangane\" width=\"96\" height=\"120\" style=\"display:block;width:96px;height:120px;border-radius:8px;border:0;\">\n              </td>\n              <td valign=\"top\" style=\"padding-top:2px;\">\n                <div style=\"font-size:16px;font-weight:700;margin:0 0 4px;\">Mika Zangane</div>\n                <div style=\"font-size:12px;color:#6b7280;margin:0 0 10px;\">Vertrieb</div>\n                <div style=\"font-size:13px;font-weight:700;margin:0 0 8px;\">NEONTRIP&reg;</div>\n                <div style=\"font-size:13px;line-height:1.6;\">\n                  Tel: <a href=\"tel:+4921154257240\" style=\"color:#111111;text-decoration:none;\">+49 211 54257240</a><br>\n                  E-Mail: <a href=\"mailto:support@neontrip.de\" style=\"color:#111111;text-decoration:none;\">support@neontrip.de</a><br>\n                  Web: <a href=\"https://www.neontrip.de\" style=\"color:#111111;text-decoration:none;\">www.neontrip.de</a><br>\n                  Bilker Allee 29, 40219 Düsseldorf\n                </div>\n              </td>\n            </tr></tbody></table>\n          </td></tr>\n          <tr><td style=\"padding:18px 16px;background:#121212;border-radius:10px;text-align:center;\">\n            <img src=\"https://cdn.shopify.com/s/files/1/0534/7819/5350/files/weiss_logo_NEONTRIP.png?v=1764003450\" alt=\"NEONTRIP\" width=\"420\" style=\"display:block;width:100%;max-width:420px;height:auto;border:0;margin:0 auto;\">\n            <div style=\"margin-top:8px;font-size:11px;font-weight:700;letter-spacing:.6px;color:#fff;\">UNIQUE LIGHTING AND BRANDING</div>\n          </td></tr>\n        </tbody>\n      </table>";
const footer=r.is_test
 ? '<p style="font:11px Arial;color:#666">Interner Versandtest. Der persönliche Abmeldelink wird ausschließlich bei einer Kundenmail nach aktueller Shopify-Prüfung eingesetzt.</p>'
 : '<p style="font:11px Arial;color:#666">Sie möchten keine solchen E-Mails mehr erhalten? <a href="'+htmlEscape(r.unsubscribe_url)+'">Abmelden</a></p>';
const body=template+footer;
const subject=(r.is_test?'[INTERNER TEST] ':'')+'Steht bei Ihnen ein neues Projekt an?';
const graph_draft={subject,body:{contentType:'HTML',content:body},toRecipients:[{emailAddress:{address:r.customer_email}}],replyTo:[{emailAddress:{address:'support@neontrip.de',name:'Mika Zangane · NEONTRIP'}}],internetMessageHeaders:[{name:'X-NEONTRIP-Repeat-Business-Id',value:r.id}]};
return [{json:{...r,route:'draft',subject,body,evidence,graph_draft}}];

const r=$json;
if(r.route==='stop') return []; // No reservation exists; preserve the database hold without a finish RPC.
if(r.route!=='reserved') return [];
if(!r.id || !r.claim_token || !Array.isArray(r.organization_emails)) throw new Error('invalid_reservation');
const email=String(r.customer_email||'').trim().toLowerCase();
if(!/^[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(email)) throw new Error('invalid_recipient');
if(r.is_test ? email!=='support@neontrip.de' : /@(neontrip\.de|riesenobjekte\.de|example\.com)$/.test(email)) throw new Error('recipient_scope_mismatch');
if(r.organization_emails.length>50 || r.organization_emails.some(e=>!e||/["\\]/.test(e))) return [{json:{...r,route:'skip',reason:'organization_lookup_requires_manual_review'}}];
const search=r.organization_emails.map(e=>'email:"'+e+'"').join(' OR ');
return [{json:{...r,route:'check',shopify_request:{query:"query RepeatBusinessLiveCheck($search: String!) { shop { name myshopifyDomain } customers(first: 50, query: $search) { nodes { id note numberOfOrders defaultEmailAddress { emailAddress marketingState marketingUpdatedAt marketingUnsubscribeUrl } orders(first: 50, sortKey: CREATED_AT, reverse: true) { nodes { id note createdAt cancelledAt displayFinancialStatus displayFulfillmentStatus } pageInfo { hasNextPage endCursor } } } pageInfo { hasNextPage endCursor } } }",variables:{search}}}}];

const r=$('ValidateReservation').first().json;
const d=$json.data;
if($json.errors || !d || d.shop?.myshopifyDomain!=='galaxybuzzdk.myshopify.com' || d.shop?.name!=='NEONTRIP') throw new Error('shopify_live_check_failed');
const skip=reason=>[{json:{...r,route:'skip',reason}}];
if(r.is_test) return [{json:{...r,route:'check',request_ids:[],trello_request_urls:['/boards/62bae9b97705e7419ed64593?fields=id%2Cname'],trello_urls:'/boards/62bae9b97705e7419ed64593?fields=id%2Cname',evidence:{mode:'internal_test',shop:d.shop.myshopifyDomain}}}];
if(d.customers?.pageInfo?.hasNextPage) return skip('shopify_customer_lookup_incomplete');
const cs=d.customers?.nodes||[];
const normalized=c=>String(c.defaultEmailAddress?.emailAddress||'').trim().toLowerCase();
const required=r.organization_order_emails||r.verification?.organization_order_emails;
if(!Array.isArray(required)||!required.includes(r.customer_email)) throw new Error('organization_order_coverage_missing');
if(cs.some(c=>!r.organization_emails.includes(normalized(c))) || required.some(e=>cs.filter(c=>normalized(c)===e).length!==1) || cs.some(c=>cs.filter(x=>normalized(x)===normalized(c)).length!==1)) return skip('shopify_buyer_identity_incomplete');
const selected=cs.find(c=>normalized(c)===r.customer_email);
if(!selected) return skip('shopify_selected_customer_missing');
// Daniel confirmed consent outside Shopify. Never invent a Shopify subscription.
// Explicit stored opt-outs remain held for review; unmaintained subscription fields do not block.
if(cs.some(c=>c.defaultEmailAddress?.marketingState==='UNSUBSCRIBED')) return skip('explicit_shopify_opt_out_requires_review');
const unsub=String(selected.defaultEmailAddress.marketingUnsubscribeUrl||'');
if(!/^https:\/\/(www\.)?neontrip\.de\//.test(unsub)||/[<>"\r\n]/.test(unsub)) return skip('unsubscribe_url_invalid');
const ids=new Set();
const cutoff=Date.now()-30*86400000;
const identifiers=text=>{
 const value=String(text||'');
 const uuid=/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/ig;
 const ticket=/\b0441-\d{4,10}(?:-\d{4,10})?\b/g;
 const found=[...value.matchAll(uuid),...value.matchAll(ticket)].map(m=>m[0].toLowerCase());
 const remainder=value.replace(uuid,' ').replace(ticket,' ');
 found.push(...[...remainder.matchAll(/(?:^|[^a-z0-9-])([0-9]{10})(?![a-z0-9-])/ig)].map(m=>m[1]));
 return [...new Set(found)];
};
for(const c of cs){
 const orders=c.orders?.nodes||[];
 if(c.orders?.pageInfo?.hasNextPage || orders.length!==Number(c.numberOfOrders)) return skip('shopify_order_history_incomplete');
 for(const o of orders){
   if(o.cancelledAt || ['REFUNDED','PARTIALLY_REFUNDED','VOIDED'].includes(o.displayFinancialStatus)) return skip('cancelled_or_refunded_order_history');
   if(!Number.isFinite(Date.parse(o.createdAt)) || Date.parse(o.createdAt)>=cutoff) return skip('company_purchased_within_30_days');
   if(o.displayFinancialStatus!=='PAID'||o.displayFulfillmentStatus!=='FULFILLED') return skip('order_not_paid_and_fulfilled');
   const found=identifiers(o.note);
   if(found.length===0) return skip('order_missing_trello_identifier');
   found.forEach(id=>ids.add(id));
 }
 identifiers(c.note).forEach(id=>ids.add(id));
}
if(ids.size===0||ids.size>10) return skip('trello_identifier_coverage_requires_review');
const request_ids=[...ids];
const trello_request_urls=request_ids.flatMap(id=>['is:open','is:archived'].map(state=>'/search?query='+encodeURIComponent(id+' '+state)+'&idBoards=62bae9b97705e7419ed64593&modelTypes=cards&card_fields=id%2Cname%2Cdesc%2CidBoard%2CidList%2Cclosed%2Curl&cards_limit=100&partial=false'));
return [{json:{...r,route:'check',request_ids,trello_request_urls,trello_urls:trello_request_urls.slice(0,10).join(','),unsubscribe_url:unsub,evidence:{mode:'customer',recipient:r.customer_email,consent_state:'OWNER_CONFIRMED',consent_source:'daniel_thread_01a06143-4981-7b13-99d6-1519f836f022_20260903',consent_checked_at:new Date().toISOString(),shopify_marketing_state:selected.defaultEmailAddress.marketingState||null,shopify_opt_out:false,shopify_customer_id:selected.id,shop:d.shop.myshopifyDomain,shopify_order_count:cs.reduce((n,c)=>n+Number(c.numberOfOrders),0),organization_buyer_emails:required,nonbuyer_contacts_not_in_shopify:r.organization_emails.filter(e=>!cs.some(c=>normalized(c)===e))}}}];

const m=$('ReadSentMessage').first().json;
const expected=$('BuildValidatedMikaMail').first().json;
const body=String(m.body?.content||'');
// Outlook may wrap/sanitize HTML. Verify the fixed text, both exact asset URLs,
// recipient-specific opt-out URL (decoded HTML entities), and no extra recipients.
const normalize=s=>String(s).replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
const plain=normalize(body);
const phrases=['ich bin Mika von NEONTRIP','kümmere mich bei uns um den Vertrieb','Mika Zangane','Wenn gerade ein Projekt ansteht, antworten Sie mir einfach mit Ihrem Logo oder Design, der ungefähren gewünschten Breite und dem Einsatzort (innen oder außen). Falls die Details noch offen sind, reichen für den Anfang ein paar Stichworte zu Ihrer Idee.'];
m.body_hash_match=phrases.every(s=>plain.includes(s)) && body.includes('Mika_3.jpg?v=1770127459') && body.includes('weiss_logo_NEONTRIP.png?v=1764003450')
 && (expected.is_test||body.replaceAll('&amp;','&').includes(expected.unsubscribe_url))
 && (!m.ccRecipients||m.ccRecipients.length===0)&&(!m.bccRecipients||m.bccRecipients.length===0);
m.in_sent_items=m.parentFolderId===$json.id;
return [{json:m}];
